"""Render exact-page-count research notes from completed immutable reports."""
import sys,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.graphics.shapes import Drawing,Line,String,PolyLine
from xml.sax.saxutils import escape
from edge.runtime import read
OUT=ROOT/'submission';OUT.mkdir(exist_ok=True)
dev=read('report-v2-development-2024-01-01-2025-12-31.json');test=read('report-v2-test-2026-01-01-2026-08-31.json')
if not dev or not test:raise SystemExit('Both fixed-window reports are required before final notes can be built.')
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='Body11',fontName='Helvetica',fontSize=11,leading=14,spaceAfter=7))
styles['Heading1'].fontSize=23;styles['Heading1'].leading=26;styles['Heading1'].textColor=colors.HexColor('#12362f')
styles['Heading2'].fontSize=13;styles['Heading2'].leading=16;styles['Heading2'].textColor=colors.HexColor('#126c59');styles['Heading2'].spaceBefore=10

def p(s,style='Body11'):return Paragraph(s,styles[style])
def h(s):return p(s,'Heading2')
def bps(x):return 'N/A' if x is None else f'{x*10000:+.1f}'
def pct(x):return 'N/A' if x is None else f'{x*100:.2f}%'
def stat(r):return next(x for x in r['horizons'] if x['horizon']==21)['groups']['standalone']
def ci(s):return 'N/A' if not s.get('interval') else f'{bps(s["interval"][0])} to {bps(s["interval"][1])}'
def table(rows,widths):
    t=Table([[p(str(v)) for v in row] for row in rows],colWidths=widths,repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e8f1ed')),('LINEBELOW',(0,0),(-1,0),1,colors.HexColor('#789a90')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('LINEBELOW',(0,1),(-1,-1),.3,colors.HexColor('#dbe4e0'))]))
    return t

def footer(canvas,doc):
    canvas.saveState();canvas.setFont('Helvetica',11);canvas.setFillColor(colors.HexColor('#596c66'));canvas.drawString(72,37,'FILING EDGE | Gator Quant Hacks | Research, not live trading');canvas.drawRightString(540,37,str(doc.page));canvas.restoreState()
def build(name,story):SimpleDocTemplate(str(OUT/name),pagesize=(612,792),leftMargin=72,rightMargin=72,topMargin=54,bottomMargin=60).build(story,onFirstPage=footer,onLaterPages=footer)

def result_table():
    rows=[['Horizon','Dev pairs','Dev diff bps','Test pairs','Test diff bps']]
    for a,b in zip(dev['horizons'],test['horizons']):
        x,y=a['groups']['standalone'],b['groups']['standalone']
        rows.append([str(a['horizon']),x['pairs'],bps(x['edge']),y['pairs'],bps(y['edge'])])
    return table(rows,[64,85,107,85,127])


def uncertainty_table():
    rows=[['Horizon','Development: n / diff / interval','Test: n / diff / interval']]
    for a,b in zip(dev['horizons'],test['horizons']):
        x,y=a['groups']['standalone'],b['groups']['standalone']
        rows.append([str(a['horizon']),f"{x['pairs']} pairs / {bps(x['edge'])} bps<br/>{ci(x)}",f"{y['pairs']} pairs / {bps(y['edge'])} bps<br/>{ci(y)}"])
    return table(rows,[58,205,205])

D,T=stat(dev),stat(test)
method='Fixed 100-issuer universe; buyback tag share_repurchase_program. The primary trade sells a standard, 100-share, cash-secured put, 5% OTM at the pre-filing parity reference, in the 90-180 day bucket nearest 120 days. Entry is anchor +1 session; primary exit is anchor +21. Every fixed horizon is reported. Contract selection uses pre-anchor data.'
execution='At 15:55 Eastern (12:55 on early closes), use the latest NBBO no more than 120 seconds old. Require positive sizes/prices and a spread at most 25% of midpoint. Sell at bid less 5%; buy at ask plus 5%; charge $0.65 per contract per side. Returns divide by full strike collateral. Quotes indicate prices, not guaranteed fills.'
matching='Controls use the same issuer at fixed backward offsets of 35, 50, 65 or 80 sessions, excluding nearby buybacks. Choose the closest pre-anchor premium/strike and maturity, with premium ratio at most 1.5 and maturity difference at most 35 days. No future return selects the control; unmatched events remain eligible for portfolio entry.'
limits='Historical tag availability is unverified; one-session availability is assumed. A static 2026 universe introduces selection bias. The spot proxy uses American put-call parity with daily closes, 4% interest and no dividend adjustment. Early assignment is not reconstructed. Pair deletion for missing quotes can bias results. These limits prevent live allocation.'
headline=f'Development: {D["pairs"]} complete pairs, difference {bps(D["edge"])} bps, interval {ci(D)}. Held-out test: {T["pairs"]} pairs, difference {bps(T["edge"])} bps, interval {ci(T)}. Intervals are exploratory envelopes of issuer and calendar-quarter bootstraps (1,999 draws each), not joint two-way cluster confidence intervals.'
story=[p('Filing Edge','Heading1'),p('Massive challenge research note | 2 pages'),h('1. Hypothesis'),p('Buyback disclosures may change compensation for bearing downside risk. We test whether cash-secured put returns after those filings differ from comparable ordinary dates. Insurance demand supplies the economic mechanism; a buyback authorization is not a guaranteed price floor.'),h('2. Method'),p(method),p(execution),p(matching),p('Version 1 development results were inspected. Version 2 was frozen before January-August 2026 returns were accessed. Development is 2024-2025; a judge can supply unseen dates to the identical notebook. No stock-price or earnings feed is used.'),h('5. How it would trade'),p('Reserve full strike cash; cap each issuer at 5% and total collateral at 50% of initial capital. Size at most 1% of prior option volume and 25% of displayed bid size. No overlapping issuer positions. Pause after a 10% marked drawdown. Missing marks reserve the entire strike liability. The test portfolio admitted one position and lost $795.80 on $1 million.'),PageBreak(),h('3. Results and uncertainty'),p('All differences and interval endpoints below are basis points of full strike collateral, net of costs. Intervals are exploratory envelopes of issuer and calendar-quarter bootstraps, 1,999 draws each. Only five primary test pairs and two test calendar clusters make inference fragile.'),uncertainty_table(),p('Difference = event minus control. The primary test event return was negative despite outperforming its controls. N/A means no usable comparison, not zero. Exp is a preclose buyback, not settlement. All expiry, moneyness, cost and delay cells are retained in the JSON report.'),h('4. What breaks the hypothesis'),p('Do not allocate if costs erase the effect, delayed entries fail, results concentrate in a few issuers or dates, or information timing cannot be verified. '+limits)]
build('Massive_Research_Note.pdf',story)

pfD,pfT=dev['portfolio'],test['portfolio']
def curve(r,title):
    rows=r['portfolio']['curve'];w=468;ht=145;d=Drawing(w,ht);lo=min(x['equity'] for x in rows);hi=max(x['equity'] for x in rows);span=max(1,hi-lo)
    d.add(String(0,ht-12,title,fontName='Helvetica',fontSize=11,fillColor=colors.HexColor('#12362f')))
    points=[]
    for i,x in enumerate(rows):points.extend([90+i*369/max(1,len(rows)-1),25+(x['equity']-lo)/span*91])
    d.add(PolyLine(points,strokeColor=colors.HexColor('#167b63'),strokeWidth=1.4))
    d.add(String(0,112,f'${hi:,.0f}',fontSize=11));d.add(String(0,24,f'${lo:,.0f}',fontSize=11));d.add(String(90,6,rows[0]['day'],fontSize=11));d.add(String(388,6,rows[-1]['day'],fontSize=11));return d
story=[p('Filing Edge','Heading1'),p('Systematic Trading | Research and decision system'),h('Executive summary'),p('A reproducible research desk that connects corporate disclosures to options, costs, capacity and a documented allocation decision. Its useful output can be a rejection: research results are not converted into a trading signal without evidence.'),p(headline),h('Economic foundation'),p('Selling downside protection earns premium in exchange for a contingent purchase obligation. The other side may value insurance or immediate liquidity. A buyback disclosure might change the distribution of future returns or insurance demand, but authorization does not ensure actual repurchases. This is a falsifiable conditional risk-premium hypothesis, not a claim of arbitrage.'),h('Innovation and product value'),p('The system joins exact filing accessions with contract selection, timestamped quotes, event/control comparisons and funded capital accounting. It exposes missingness and preserves the original pilot. Gemini explains exact source excerpts with quote validation; Tiger Data stores experiments and serves precomputed daily activity; ElevenLabs narrates the computed decision with a visible transcript.'),h('Current allocation decision'),p('RESEARCH ONLY. '+limits),PageBreak(),p('Data and methodology','Heading1'),h('Data contract'),p('Massive supplies 8-K disclosures, option reference contracts, option daily trades and historical NBBO. Raw licensed responses and credentials remain local. Only standard contracts are included. Results are truncated at each window end; future labels and exits are not silently filled.'),p(method),h('Execution and matching'),p(execution),p(matching),h('Time and validation'),p('The filing date maps to the next eligible exchange session; tag availability is assumed one session later. This is not proof of first public dissemination. US exchange holidays and early closes are handled explicitly. Tests exercise quote timestamps, crossed quotes, missing exits, cash conservation, collateral limits and assignment cashflows.'),h('Reproducibility'),p('Use submission/Filing_Edge_Judge.ipynb in a clean Python 3.11+ kernel, or judge.py with --start, --end and --mode sealed. The notebook embeds checksummed source and asks for only a Massive key. Research hashes and first-access manifests are immutable within each workspace.'),PageBreak(),p('Results across fixed horizons','Heading1'),p(headline),result_table(),h('Reading the result correctly'),p('The held-out event return is negative even though its difference from worse-performing controls is positive. Five pairs across only two calendar quarters cannot support a strong allocation conclusion.'),p('The primary horizon is 21 sessions. Other horizons, entry delays of 1/2/3/5 sessions, haircuts of 2.5/5/10%, expiry buckets and OTM levels are exploratory sensitivity checks, not a search for the best result. Full cell counts, intervals and exclusions are exported in JSON.'),h('Missingness and confounding'),p(f'Development covered {dev["event_count"]} events; test covered {test["event_count"]}. Complete pair counts can vary across cells. Filtering wide or unavailable quotes improves realism but can change the population. Premium and maturity matching does not remove omitted risk factors or establish causality.'),PageBreak(),p('Funded portfolio and risk','Heading1'),table([['Metric','Development','Held-out test'],['Total account return',pct(pfD['total_return']),pct(pfT['total_return'])],['Annualized return (CAGR)',pct(pfD['cagr']),pct(pfT['cagr'])],['Annualized volatility',pct(pfD['annualized_volatility']),pct(pfT['annualized_volatility'])],['Sharpe, zero cash benchmark',str(round(pfD['sharpe_zero_cash'],2)) if pfD['sharpe_zero_cash'] is not None else 'N/A',str(round(pfT['sharpe_zero_cash'],2)) if pfT['sharpe_zero_cash'] is not None else 'N/A'],['Maximum drawdown',pct(pfD['max_drawdown']),pct(pfT['max_drawdown'])],['Premium cash turnover / year',f'{pfD["premium_cash_turnover_per_year"]:.4f}x',f'{pfT["premium_cash_turnover_per_year"]:.4f}x'],['Positions admitted',pfD['trade_count'],pfT['trade_count']]], [232,118,118]),curve(dev,'Development account equity'),curve(test,'Held-out account equity'),p('Initial capital is $1 million in each independent window. Idle cash earns zero. Turnover counts traded option premium, not underlying notional. No leverage. Missing marks use a full-strike liability reserve, a pessimistic accounting bound that can dominate volatility and trigger the entry pause.'),PageBreak(),p('Liquidity, limitations and delivery','Heading1'),h('Capital and capacity'),p('Per-issuer allocation is 5% of initial equity; total reserved strike collateral is at most 50%. Quantity is the minimum allowed by cash, lagged 20-observation option volume (at least five observations), 1% participation and 25% displayed bid size. This is a conservative size constraint, not a calibrated market-impact capacity estimate. Scaling requires depth and fill studies.'),h('Assignment and operational controls'),p('Physical put assignment pays strike times 100 shares per contract and receives shares. Unit-tested scenarios value their liquidation at shocked prices. Actual historical exercise notices, overnight stock execution, dividends, borrow and taxes are absent. Open positions remain reserved at the cutoff. Consequently the model cannot claim a complete historical exercise lifecycle.'),h('What would justify further work'),p('Archive live disclosure arrival times, validate a point-in-time universe, cross-check parity against permitted reference data, reconstruct dividends and assignment, and paper trade quoted orders. Predeclare any revised method before gathering new evaluation data. Do not reuse the evaluated 2026 window as an untouched test.'),h('Submission and sponsor use'),p('The repository contains the application, standalone judge notebook, frozen configuration, tests, deployment files, both research notes and a demo script. API keys stay server-side. Gemini explanations cannot modify signals. ElevenLabs audio is labeled AI-generated and includes its exact report-derived transcript. Tiger Data persists provenance and uses a Timescale continuous aggregate for daily queries.'),h('Sources and audit trail'),p('Challenge: gqhacks.com/tracks/systematic-trading and the supplied GQH Massive 8-K options starter notebook. Data documentation: massive.com/docs. Sponsor documentation: docs.tigerdata.com, ai.google.dev/gemini-api/docs, elevenlabs.io/docs. Source citations in filing evidence link to SEC EDGAR. See STARTER_AUDIT.md and submission/research-manifest.json for method hashes and access timestamps.')]
build('Systematic_Trading_Note.pdf',story)
